#!/usr/bin/env bash
# {{NAME}} — generated by TERMy ({{LANG}})
# Assumes the input array is already sorted.
set -euo pipefail

binary_search() {
    local target="$1"; shift
    local arr=("$@") low=0 high=$(( ${#arr[@]} - 1 )) mid
    while (( low <= high )); do
        mid=$(( (low + high) / 2 ))
        if (( arr[mid] == target )); then
            printf 'Found %s at index %s\n' "$target" "$mid"; return 0
        fi
        if (( arr[mid] < target )); then low=$((mid + 1)); else high=$((mid - 1)); fi
    done
    printf '%s not found\n' "$target"; return 1
}

binary_search {{TARGET}} {{ARRAY}}